	static PyObject *Pipeline_loadShader(PYPipeline *self, PyObject *args, PyObject *kwargs) {
		uint32_t type = 0;
		const char *name = nullptr;
		PyObject *macros_ = nullptr;
		PyObject *includes_ = nullptr;
		uint32_t size = 0;
		static const char *kwlist[] = { "type", "name", "macros", "includes", nullptr };
		while(PyArg_ParseTupleAndKeywords(args, kwargs, "Is|OO", (char**)kwlist, &type, &name, &macros_, &includes_)) {
			const String &macros = (macros_) ? ((PyUnicode_Check(macros_)) ? String(PyUnicode_AsUTF8(macros_)) : (String)pyString_get(macros_)) : String::null;
			const char **includes; Array<const char*> includes__;
			pyArray_get(includes_, includes__); includes = includes__.get();
			return PyLong_FromLong(self->ptr.loadShader((Shader::Type)type, name, macros, includes, size = includes__.size()));
		}
		#if TS_DEBUG
			PyErr_SetString(PyExc_TypeError, "Pipeline::loadShader(): unknown arguments:\n(Shader.Type type, const char* name, const String macros, const char** includes, uint32_t size) -> bool\n");
		#else
			pyBadArguments();
		#endif
		return nullptr;
	}
