	// Tellusim::CanvasElement
	static bool pyCanvasElement_DrawCallback(Command command, CanvasElement element, PyObject *func) {
		bool ret = {};
		PyObject *command_ = pyCommand_new(command);
		PyObject *element_ = pyCanvasElement_new(element);
		if(func) {
			PyObject *args = Py_BuildValue("(OO)", command_, element_);
			PyObject *ret_ = PyObject_CallObject(func, args);
			if(ret_) {
				ret = (Py_IsTrue(ret_) != 0);
				Py_DECREF(ret_);
			} else if(PyErr_Occurred()) {
				PyErr_PrintEx(0);
				PyErr_Clear();
			}
			Py_DECREF(args);
		}
		Py_DECREF(element_);
		Py_DECREF(command_);
		return ret;
	}
