	static bool pyCanvas_CreateCallback(const Device device, Canvas canvas, uint32_t scale, PyObject *func) {
		bool ret = {};
		PyObject *device_ = pyDevice_new(device);
		PyObject *canvas_ = pyCanvas_new(canvas);
		if(func) {
			PyObject *args = Py_BuildValue("(OOI)", device_, canvas_, scale);
			PyObject *ret_ = PyObject_CallObject(func, args);
			if(ret_) {
				ret = (Py_IsTrue(ret_) != 0);
				Py_DECREF(ret_);
			} else if(PyErr_Occurred()) {
				PyErr_PrintEx(0);
				PyErr_Clear();
			}
			Py_DECREF(args);
		}
		Py_DECREF(canvas_);
		Py_DECREF(device_);
		return ret;
	}
