	static bool pyDialogMessage_UpdateCallback(PyObject *func) {
		bool ret = {};
		if(func) {
			PyObject *args = Py_BuildValue("()");
			PyObject *ret_ = PyObject_CallObject(func, args);
			if(ret_) {
				ret = (Py_IsTrue(ret_) != 0);
				Py_DECREF(ret_);
			} else if(PyErr_Occurred()) {
				PyErr_PrintEx(0);
				PyErr_Clear();
			}
			Py_DECREF(args);
		}
		return ret;
	}
