	static void pyController_ButtonPressedCallback(Controller controller, Controller::Button button, PyObject *func) {
		PyObject *controller_ = pyController_new(controller);
		if(func) {
			PyObject *args = Py_BuildValue("(OI)", controller_, button);
			PyObject *ret_ = PyObject_CallObject(func, args);
			if(ret_) {
				Py_DECREF(ret_);
			} else if(PyErr_Occurred()) {
				PyErr_PrintEx(0);
				PyErr_Clear();
			}
			Py_DECREF(args);
		}
		Py_DECREF(controller_);
	}
